  "common.cancel": "\u0c30\u0c26\u0c4d\u0c26\u0c41 \u0c1a\u0c47\u0c2f\u0c02\u0c21\u0c3f",
  "common.close": "\u0c2e\u0c42\u0c38\u0c3f\u0c35\u0c47\u0c2f\u0c3f",
