  "common.required": "\u0c08 \u0c2b\u0c40\u0c32\u0c4d\u0c21\u0c4d \u0c05\u0c35\u0c38\u0c30\u0c02",
  "common.viewProfile": "\u0c2a\u0c4d\u0c30\u0c4a\u0c2b\u0c48\u0c32\u0c4d \u0c1a\u0c42\u0c21\u0c02\u0c21\u0c3f",
  "landing.hero.badge": "100% \u0c09\u0c1a\u0c3f\u0c24\u0c02 \u0c2e\u0c30\u0c3f\u0c2f\u0c41 \u0c2a\u0c4d\u0c30\u0c48\u0c35\u0c47\u0c1f\u0c41",
  "landing.hero.h1": "\u0c2e\u0c40 \u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c38\u0c30\u0c48\u0c28 \u0c2a\u0c4d\u0c30\u0c2d\u0c41\u0c24\u0c4d\u0c35 \u0c2a\u0c25\u0c15\u0c3e\u0c32\u0c28\u0c41 \u0c15\u0c28\u0c41\u0c17\u0c4a\u0c28\u0c02\u0c21\u0c3f",
  "landing.hero.h1.accent": "\u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30\u0c02",
  "landing.hero.sub": "VittVanni \u0c2d\u0c3e\u0c30\u0c24\u0c26\u0c47\u0c36\u0c2a\u0c41 \u0c15\u0c47\u0c02\u0c26\u0c4d\u0c30, \u0c30\u0c3e\u0c37\u0c4d\u0c1f\u0c4d\u0c30 \u0c2a\u0c4d\u0c30\u0c2d\u0c41\u0c24\u0c4d\u0c35 \u0c2a\u0c25\u0c15\u0c3e\u0c32\u0c28\u0c41 \u0c2e\u0c40 \u0c2a\u0c4d\u0c30\u0c4a\u0c2b\u0c48\u0c32\u0c4d\u0c24\u0c4b \u0c38\u0c30\u0c3f\u0c2a\u0c4b\u0c32\u0c41\u0c38\u0c4d\u0c24\u0c41\u0c02\u0c26\u0c3f \u2014 \u0c38\u0c41\u0c32\u0c2d \u0c24\u0c46\u0c32\u0c41\u0c17\u0c41, \u0c26\u0c36\u0c32\u0c35\u0c3e\u0c30\u0c40\u0c17\u0c3e.",
  "landing.hero.cta": "\u0c38\u0c30\u0c3f\u0c2a\u0c4b\u0c32\u0c3f\u0c15 \u0c2a\u0c4d\u0c30\u0c3e\u0c30\u0c02\u0c2d\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f",
  "landing.hero.cta2": "\u0c07\u0c26\u0c3f \u0c0e\u0c32\u0c3e \u0c2a\u0c28\u0c3f \u0c1a\u0c47\u0c38\u0c4d\u0c24\u0c41\u0c02\u0c26\u0c3f",
  "landing.how.title": "\u0c07\u0c26\u0c3f \u0c0e\u0c32\u0c3e \u0c2a\u0c28\u0c3f \u0c1a\u0c47\u0c38\u0c4d\u0c24\u0c41\u0c02\u0c26\u0c3f",
  "landing.how.1.title": "\u0c2e\u0c40 \u0c17\u0c41\u0c30\u0c3f\u0c02\u0c1a\u0c3f \u0c1a\u0c46\u0c2a\u0c4d\u0c2a\u0c02\u0c21\u0c3f",
  "landing.how.1.text": "\u0c2e\u0c40 \u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30\u0c02, \u0c2a\u0c4d\u0c30\u0c3e\u0c02\u0c24\u0c02, \u0c28\u0c47\u0c2a\u0c25\u0c4d\u0c2f\u0c02 \u0c17\u0c41\u0c30\u0c3f\u0c02\u0c1a\u0c3f 9 \u0c38\u0c41\u0c32\u0c2d \u0c2a\u0c4d\u0c30\u0c36\u0c4d\u0c28\u0c32\u0c15\u0c41 \u0c38\u0c2e\u0c3e\u0c27\u0c3e\u0c28\u0c02 \u0c07\u0c35\u0c4d\u0c35\u0c02\u0c21\u0c3f.",
  "landing.how.2.title": "\u0c2e\u0c47\u0c2e\u0c41 \u0c2e\u0c3f\u0c2e\u0c4d\u0c2e\u0c32\u0c4d\u0c28\u0c3f \u0c38\u0c30\u0c3f\u0c2a\u0c4b\u0c32\u0c41\u0c38\u0c4d\u0c24\u0c3e\u0c2e\u0c41",
  "landing.how.2.text": "\u0c2e\u0c3e \u0c35\u0c4d\u0c2f\u0c35\u0c38\u0c4d\u0c25 \u0c2e\u0c40 \u0c38\u0c2e\u0c3e\u0c27\u0c3e\u0c28\u0c3e\u0c32 \u0c28\u0c41\u0c02\u0c21\u0c3f 14 \u0c30\u0c02\u0c17\u0c3e\u0c32\u0c4d\u0c32\u0c4b 90+ \u0c2a\u0c25\u0c15\u0c3e\u0c32\u0c28\u0c41 \u0c30\u0c4d\u0c2f\u0c3e\u0c02\u0c15\u0c4d \u0c1a\u0c47\u0c38\u0c4d\u0c24\u0c41\u0c02\u0c26\u0c3f.",
  "landing.how.3.title": "\u0c35\u0c3f\u0c35\u0c30\u0c23 \u0c2a\u0c4a\u0c02\u0c26\u0c02\u0c21\u0c3f",
  "landing.how.3.text": "\u0c2a\u0c4d\u0c30\u0c24\u0c3f \u0c2a\u0c25\u0c15\u0c02 \u0c0e\u0c02\u0c26\u0c41\u0c15\u0c41 \u0c38\u0c30\u0c3f\u0c2a\u0c4b\u0c24\u0c41\u0c02\u0c26\u0c4b \u0c38\u0c4d\u0c2a\u0c37\u0c4d\u0c1f\u0c2e\u0c48\u0c28 \u0c15\u0c3e\u0c30\u0c23\u0c3e\u0c32\u0c41 \u2014 \u0c15\u0c37\u0c4d\u0c1f\u0c2e\u0c48\u0c28 \u0c2a\u0c26\u0c3e\u0c32\u0c41 \u0c32\u0c47\u0c15\u0c41\u0c02\u0c21\u0c3e.",
  "landing.how.4.title": "\u0c35\u0c3f\u0c36\u0c4d\u0c35\u0c3e\u0c38\u0c02\u0c24\u0c4b \u0c26\u0c30\u0c16\u0c3e\u0c38\u0c4d\u0c24\u0c41 \u0c1a\u0c47\u0c2f\u0c02\u0c21\u0c3f",
  "landing.how.4.text": "\u0c2a\u0c24\u0c4d\u0c30\u0c3e\u0c32\u0c41, \u0c24\u0c47\u0c26\u0c40\u0c32\u0c41 \u0c2e\u0c30\u0c3f\u0c2f\u0c41 \u0c35\u0c3e\u0c30\u0c02\u0c35\u0c3e\u0c30\u0c40 \u0c26\u0c30\u0c16\u0c3e\u0c38\u0c4d\u0c24\u0c41 \u0c2e\u0c3e\u0c30\u0c4d\u0c17\u0c26\u0c30\u0c4d\u0c36\u0c3f\u0c28\u0c3f \u0c2a\u0c4a\u0c02\u0c26\u0c02\u0c21\u0c3f.",
  "landing.stats.title": "\u0c0e\u0c26\u0c41\u0c17\u0c41\u0c24\u0c41\u0c28\u0c4d\u0c28 \u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30\u0c35\u0c47\u0c24\u0c4d\u0c24\u0c32 \u0c28\u0c2e\u0c4d\u0c2e\u0c15\u0c02",
  "landing.stats.schemes": "\u0c15\u0c35\u0c30\u0c4d \u0c1a\u0c47\u0c38\u0c3f\u0c28 \u0c2a\u0c25\u0c15\u0c3e\u0c32\u0c41",
  "landing.stats.sectors": "\u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30 \u0c30\u0c02\u0c17\u0c3e\u0c32\u0c41",
  "landing.stats.states": "\u0c15\u0c35\u0c30\u0c4d \u0c1a\u0c47\u0c38\u0c3f\u0c28 \u0c30\u0c3e\u0c37\u0c4d\u0c1f\u0c4d\u0c30\u0c3e\u0c32\u0c41",
  "landing.stats.languages": "\u0c2d\u0c3e\u0c37\u0c32\u0c41",
  "landing.features.title": "\u0c28\u0c3f\u0c1c\u0c2e\u0c48\u0c28 \u0c35\u0c4d\u0c2f\u0c3e\u0c2a\u0c3e\u0c30\u0c35\u0c47\u0c24\u0c4d\u0c24\u0c32 \u0c15\u0c4b\u0c38\u0c02 \u0c30\u0c42\u0c2a\u0c4a\u0c02\u0c26\u0c3f\u0c02\u0c1a\u0c2c\u0c21\u0c3f\u0c02\u0c26\u0c3f",
  "landing.features.1.title": "\u0c2e\u0c41\u0c02\u0c26\u0c41\u0c17\u0c3e \u0c35\u0c3e\u0c2f\u0c3f\u0c38\u0c4d + \u0c1f\u0c46\u0c15\u0c4d\u0c38\u0c4d\u0c1f\u0c4d",
  "landing.features.1.text": "\u0c0f \u0c2b\u0c4b\u0c28\u0c4d\u0c32\u0c4b\u0c28\u0c48\u0c28\u0c3e, \u0c24\u0c15\u0c4d\u0c15\u0c41\u0c35 \u0c21\u0c47\u0c1f\u0c3e\u0c24\u0c4b \u0c24\u0c47\u0c32\u0c3f\u0c15\u0c17\u0c3e \u0c28\u0c21\u0c3f\u0c1a\u0c47 \u0c30\u0c42\u0c2a\u0c15\u0c32\u0c4d\u0c2a\u0c28.",
  "landing.features.2.title": "23 \u0c2d\u0c3e\u0c37\u0c32\u0c41",
  "landing.features.2.text": "\u0c2a\u0c48 \u0c2e\u0c46\u0c28\u0c42\u0c32\u0c4b \u0c28\u0c41\u0c02\u0c21\u0c3f \u0c0f \u0c2d\u0c3e\u0c30\u0c24\u0c40\u0c2f \u0c2d\u0c3e\u0c37\u0c28\u0c48\u0c28\u0c3e \u0c0e\u0c02\u0c1a\u0c41\u0c15\u0c4b\u0c02\u0c21\u0c3f.",
  "landing.features.3.title": "\u0c06\u0c2b\u0c4d\u0c32\u0c48\u0c28\u0c4d-\u0c38\u0c4d\u0c28\u0c47\u0c39\u0c2a\u0c42\u0c30\u0c4d\u0c35\u0c15\u0c02",
  "landing.features.3.text": "\u0c2a\u0c25\u0c15\u0c3e\u0c32\u0c41 \u0c32\u0c4b\u0c15\u0c32\u0c4d \u0c15\u0c4d\u0c2f\u0c3e\u0c37\u0c4d\u0c32\u0c4b \u0c09\u0c02\u0c1f\u0c3e\u0c2f\u0c3f \u2014 \u0c07\u0c02\u0c1f\u0c30\u0c4d\u0c28\u0c46\u0c1f\u0c4d \u0c32\u0c47\u0c15\u0c41\u0c02\u0c21\u0c3e\u0c28\u0c47 \u0c1a\u0c42\u0c21\u0c35\u0c1a\u0c4d\u0c1a\u0c41.",
  "landing.features.4.title": "\u0c2e\u0c41\u0c02\u0c26\u0c41\u0c17\u0c3e \u0c17\u0c4b\u0c2a\u0c4d\u0c2f\u0c24",
  "landing.features.4.text": "\u0c2e\u0c40 \u0c21\u0c47\u0c1f\u0c3e \u0c2e\u0c40\u0c26\u0c47 \u0c09\u0c02\u0c1f\u0c41\u0c02\u0c26\u0c3f. \u0c0e\u0c2a\u0c4d\u0c2a\u0c1f\u0c3f\u0c15\u0c40 \u0c05\u0c2e\u0c4d\u0c2e\u0c2c\u0c21\u0c26\u0c41.",
  "landing.cta.title": "\u0c2e\u0c40 \u0c2a\u0c25\u0c15\u0c3e\u0c28\u0c4d\u0c28\u0c3f \u0c15\u0c28\u0c41\u0c17\u0c4a\u0c28\u0c21\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c38\u0c3f\u0c26\u0c4d\u0c27\u0c2e\u0c3e?",
  "landing.cta.text": "\u0c07\u0c02\u0c26\u0c41\u0c15\u0c41 5 \u0c28\u0c3f\u0c2e\u0c3f\u0c37\u0c3e\u0c32 \u0c15\u0c02\u0c1f\u0c47 \u0c24\u0c15\u0c4d\u0c15\u0c41\u0c35 \u0c38\u0c2e\u0c2f\u0c02 \u0c2a\u0c21\u0c41\u0c24\u0c41\u0c02\u0c26\u0c3f.",
  "auth.login.title": "\u0c38\u0c4d\u0c35\u0c3e\u0c17\u0c24\u0c02",
  "auth.login.sub": "\u0c38\u0c30\u0c3f\u0c2a\u0c4b\u0c32\u0c3f\u0c15 \u0c2a\u0c4d\u0c30\u0c2f\u0c3e\u0c23\u0c3e\u0c28\u0c4d\u0c28\u0c3f \u0c15\u0c4a\u0c28\u0c38\u0c3e\u0c17\u0c3f\u0c02\u0c1a\u0c21\u0c3e\u0c28\u0c3f\u0c15\u0c3f \u0c32\u0c3e\u0c17\u0c3f\u0c28\u0c4d \u0c1a\u0c47\u0c2f\u0c02\u0c21\u0c3f",
  "auth.register.title": "\u0c16\u0c3e\u0c24\u0c3e\u0c28\u0c41 \u0c38\u0c43\u0c37\u0c4d\u0c1f\u0c3f\u0c02\u0c1a\u0c02\u0c21\u0c3f",
  "auth.register.sub": "\u0c0e\u0c32\u0c4d\u0c32\u0c2a\u0c4d\u0c2a\u0c41\u0c21\u0c42 \u0c09\u0c1a\u0c3f\u0c24\u0c02. \u0c38\u0c46\u0c15\u0c28\u0c4d\u0c32\u0c32\u0c4b \u0c28\u0c2e\u0c4b\u0c26\u0c41 \u0c1a\u0c47\u0c38\u0c41\u0c15\u0c4b\u0c02\u0c21\u0c3f.",
  "auth.email": "\u0c07\u0c2e\u0c46\u0c2f\u0c3f\u0c32\u0c4d \u0c1a\u0c3f\u0c30\u0c41\u0c28\u0c3e\u0c2e\u0c3e",
