  "questionnaire.describe.pickState": "\u0c2e\u0c40\u0c30\u0c41 \u0c0f \u0c30\u0c3e\u0c37\u0c4d\u0c1f\u0c4d\u0c30\u0c02\u0c32\u0c4b \u0c2a\u0c28\u0c3f \u0c1a\u0c47\u0c38\u0c4d\u0c24\u0c3e\u0c30\u0c41?",
  "questionnaire.describe.apply": "\u0c07\u0c26\u0c47 \u0c38\u0c30\u0c3f \u2014 \u0c28\u0c3e \u0c2a\u0c25\u0c15\u0c3e\u0c32\u0c41 \u0c24\u0c40\u0c38\u0c41\u0c15\u0c41\u0c30\u0c02\u0c21\u0c3f",
